  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('5d044236-9a0e-59b5-aab4-1ef901308dbd', '{"style":"calculation","summary":"Share an amount in a ratio by finding the value of one part, and solve problems where you''re told one share or the difference between shares instead of the total.","knowledge":["Add the parts of the ratio to find the total number of parts.","Value of one part = total ÷ total number of parts.","If you''re given a difference, divide it by the difference in parts.","If you''re given one share, divide it by that share''s parts.","Check the shares add up to the total."],"vocabulary":[{"term":"Ratio","meaning":"A comparison of the sizes of two or more quantities, written like 3 : 5."},{"term":"Part","meaning":"One unit of the ratio. In 3 : 5 there are 8 parts in total."}],"recognise":"Something is ''shared'' or ''divided'' in a ratio, or the question gives a ratio and one amount.","commandWords":[{"word":"How much","meaning":"Give an amount with units — make sure it''s the share the question asks for."}],"method":[{"title":"Work out what you know","detail":"Is the amount the total, one share or a difference?"},{"title":"Find one part","detail":"Divide that amount by the matching number of parts."},{"title":"Multiply up","detail":"Multiply one part by each share''s number of parts."},{"title":"Answer the question asked","detail":"Give the share the question wants and check the shares add up."}],"mistakes":[{"tag":"misread_question","text":"Treating a difference or one person''s share as if it were the total."},{"tag":"incomplete_method","text":"Finding one part and stopping before multiplying."}],"worked":{"question":"Amy and Ben share £72 in the ratio 3 : 5. How much does Ben get?","marks":2,"steps":[{"prompt":"How many parts are there in total?","choices":[{"text":"8","correct":true,"feedback":"3 + 5 = 8 parts."},{"text":"15","correct":false,"feedback":"Add the parts, don''t multiply them.","tag":"arithmetic_slip"},{"text":"2","correct":false,"feedback":"The difference isn''t needed here — the total is.","tag":"misread_question"}],"reveal":"3 + 5 = 8 parts"},{"prompt":"What is one part worth?","choices":[{"text":"£72 ÷ 8 = £9","correct":true,"feedback":"Correct."},{"text":"£72 ÷ 5 = £14.40","correct":false,"feedback":"Divide by the total number of parts.","tag":"wrong_formula"}],"reveal":"1 part = £9"},{"prompt":"How much does Ben get?","choices":[{"text":"5 × £9 = £45","correct":true,"feedback":"Yes. Amy gets £27 and £27 + £45 = £72 ✓"},{"text":"3 × £9 = £27","correct":false,"feedback":"That''s Amy''s share. Ben has 5 parts.","tag":"misread_question"}],"reveal":"Ben gets £45"}],"finalAnswer":"£45"},"guided":[{"question":"Sweets are shared between Cal and Dev in the ratio 2 : 7. Dev gets 25 more sweets than Cal. How many sweets does Cal get?","marks":3,"answer":{"type":"numeric","value":10},"hints":["The difference in parts is 7 − 2 = 5.","5 parts = 25 sweets, so 1 part = 5 sweets.","Cal has 2 parts."],"solution":"1 part = 25 ÷ 5 = 5. Cal gets 2 × 5 = 10 sweets."}],"exam":[{"question":"Orange paint is made by mixing red and yellow paint in the ratio 2 : 3. Jo has 450 ml of yellow paint and plenty of red. What is the most orange paint she can make, in ml?","marks":3,"answer":{"type":"numeric","value":750,"unit":"ml"},"markScheme":[{"point":"3 parts = 450 ml, so 1 part = 150 ml","marks":1},{"point":"Red = 2 × 150 = 300 ml","marks":1},{"point":"750 ml","marks":1}],"modelAnswer":"Yellow is 3 parts, so 1 part = 150 ml. Total = 5 parts = 750 ml.","mistakeTags":["misread_question","incomplete_method"]}]}'::jsonb, 'published')
on conflict (topic_id) do update set content = excluded.content, status = 'published', version = public.lessons.version + 1, updated_at = now()
  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('beaaf54e-c7aa-5204-ad83-0da99f6024b2', '{"style":"explanation","summary":"Name the parts of animal and plant cells, say what each part does, and explain the differences between the two — the starting point for all of cell biology.","knowledge":["Animal and plant cells both have a nucleus, cytoplasm, cell membrane, mitochondria and ribosomes.","Plant cells also have a cell wall made of cellulose, a permanent vacuole filled with cell sap, and often chloroplasts.","The nucleus contains genetic material that controls the cell''s activities.","Mitochondria are where aerobic respiration happens; ribosomes are where proteins are made.","Chloroplasts absorb light for photosynthesis; the cell wall strengthens the cell."],"vocabulary":[{"term":"Cell membrane","meaning":"Controls which substances move into and out of the cell."},{"term":"Cytoplasm","meaning":"Gel-like substance where most chemical reactions happen."},{"term":"Chloroplast","meaning":"Contains chlorophyll, which absorbs light for photosynthesis."}],"recognise":"A labelled diagram of a cell, or a question asking you to name, describe the function of, or compare cell parts.","commandWords":[{"word":"Name","meaning":"One word or phrase is enough."},{"word":"Describe","meaning":"Say what something is like or does — no reason needed."},{"word":"Explain","meaning":"Give a reason: say why or how."}],"method":[{"title":"Identify the part","detail":"Use shape and position: chloroplasts are small green ovals, the vacuole is a large central space."},{"title":"Give its function","detail":"Match each part to its job using precise words: ''controls'', ''site of'', ''absorbs''."},{"title":"For comparisons, use both cells","detail":"Say what the plant cell has that the animal cell doesn''t, and what they share."}],"mistakes":[{"tag":"vague_language","text":"Saying mitochondria ''make energy''. Energy can''t be made: they release energy by respiration."},{"tag":"missing_key_term","text":"Saying the cell wall ''protects'' without mentioning that it strengthens and supports the cell."},{"tag":"misread_question","text":"Thinking all plant cells have chloroplasts — root cells don''t, because they get no light."}],"worked":{"question":"Explain why root hair cells do not contain chloroplasts. (2 marks)","marks":2,"steps":[{"prompt":"What do chloroplasts do?","choices":[{"text":"They absorb light for photosynthesis","correct":true,"feedback":"Yes — that''s the first idea you need."},{"text":"They release energy from glucose","correct":false,"feedback":"That''s mitochondria (respiration).","tag":"missing_key_term"},{"text":"They control the cell","correct":false,"feedback":"That''s the nucleus.","tag":"missing_key_term"}],"reveal":"Chloroplasts absorb light so the cell can photosynthesise."},{"prompt":"Now link it to root hair cells. Which reason completes the explanation?","choices":[{"text":"Roots are underground, so they receive no light to photosynthesise","correct":true,"feedback":"That''s the ''because'' that turns it into an explanation."},{"text":"Root hair cells are small","correct":false,"feedback":"Size isn''t the reason — think about where roots are.","tag":"description_not_explanation"},{"text":"Root hair cells absorb water","correct":false,"feedback":"True, but it doesn''t explain the missing chloroplasts.","tag":"not_linked_to_question"}],"reveal":"Roots are underground and get no light, so chloroplasts would be useless there."}],"finalAnswer":"Chloroplasts absorb light for photosynthesis (1). Root hair cells are underground so receive no light, so they cannot photosynthesise (1)."},"guided":[{"question":"Which part of a cell is the site of aerobic respiration?","marks":1,"answer":{"type":"choice","options":["Nucleus","Ribosome","Mitochondrion","Cell wall"],"correct":2},"hints":["Respiration releases energy from glucose.","This organelle is often called the ''powerhouse'', though it releases energy rather than making it."],"solution":"Mitochondria are the site of aerobic respiration."},{"question":"Name the substance a plant cell wall is made of.","marks":1,"answer":{"type":"text","accept":["cellulose"]},"hints":["It''s a carbohydrate polymer made from glucose.","It starts with ''c''."],"solution":"Cellulose."}],"exam":[{"question":"Give three structures found in a palisade leaf cell that are not found in an animal cell, and describe the function of each.","marks":6,"answer":{"type":"extended"},"markScheme":[{"point":"Cell wall","marks":1},{"point":"Strengthens / supports the cell","marks":1},{"point":"Permanent vacuole","marks":1},{"point":"Contains cell sap / keeps the cell firm (turgid)","marks":1},{"point":"Chloroplasts","marks":1},{"point":"Absorb light for photosynthesis","marks":1}],"modelAnswer":"A cell wall made of cellulose, which strengthens and supports the cell. A permanent vacuole filled with cell sap, which keeps the cell firm. Chloroplasts, which contain chlorophyll to absorb light for photosynthesis.","mistakeTags":["missing_key_term","vague_language"]}]}'::jsonb, 'published')
on conflict (topic_id) do update set content = excluded.content, status = 'published', version = public.lessons.version + 1, updated_at = now()
  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('d832512d-394a-5817-a4b4-12c6cf3bf737', '{"style":"explanation","summary":"Explain osmosis as the movement of water across a partially permeable membrane from a dilute to a more concentrated solution, and analyse results from the potato practical.","knowledge":["Osmosis is the diffusion of water from a dilute solution to a more concentrated solution through a partially permeable membrane.","It is passive: it needs no energy from respiration.","In a more concentrated solution, plant tissue loses water and mass; in a more dilute one it gains water and mass.","Percentage change in mass = (final − initial) ÷ initial × 100, which lets you compare pieces that started at different masses.","Where the line of a graph crosses 0% change, the solution has the same concentration as the cell contents."],"vocabulary":[{"term":"Partially permeable","meaning":"Lets small molecules like water through but not larger ones like sugar."},{"term":"Turgid","meaning":"A plant cell swollen with water, pressing on its cell wall."},{"term":"Plasmolysed","meaning":"A plant cell that has lost so much water its membrane pulls away from the wall."}],"recognise":"Questions about water moving into or out of cells, sugar or salt solutions, or results tables showing mass change of potato pieces.","commandWords":[{"word":"Explain","meaning":"Say what happens to the water and why, using ''dilute'' and ''concentrated''."},{"word":"Calculate","meaning":"Show the percentage change working."},{"word":"Suggest","meaning":"Apply what you know to an unfamiliar situation."}],"method":[{"title":"Compare the concentrations","detail":"Which side has more water (is more dilute)?"},{"title":"State the direction","detail":"Water moves from the dilute side to the concentrated side."},{"title":"Name the membrane","detail":"Say ''through a partially permeable membrane''."},{"title":"Give the result","detail":"Say what happens to the cell or tissue: gains mass and becomes turgid, or loses mass and becomes flaccid."}],"mistakes":[{"tag":"vague_language","text":"Saying water moves ''from high to low concentration'' without saying high or low concentration of what."},{"tag":"missing_key_term","text":"Missing ''partially permeable membrane''."},{"tag":"data_not_used","text":"Comparing mass changes instead of percentage changes when pieces started at different masses."}],"worked":{"question":"A potato cylinder is placed in a concentrated sugar solution. Explain what happens to its mass. (3 marks)","marks":3,"steps":[{"prompt":"Compare the concentrations. Which is more concentrated?","choices":[{"text":"The sugar solution is more concentrated than the potato cells","correct":true,"feedback":"Right — the cells contain a more dilute solution."},{"text":"The potato cells are more concentrated","correct":false,"feedback":"The question says the sugar solution is concentrated.","tag":"misread_question"}],"reveal":"The solution outside is more concentrated than the cell contents."},{"prompt":"Which way does water move, and how?","choices":[{"text":"Out of the cells by osmosis, through the partially permeable membrane","correct":true,"feedback":"Yes — from the dilute cell contents to the concentrated solution."},{"text":"Sugar moves into the cells","correct":false,"feedback":"The membrane stops sugar; osmosis is about water.","tag":"missing_key_term"},{"text":"Water moves into the cells","correct":false,"feedback":"Water moves towards the more concentrated solution.","tag":"vague_language"}],"reveal":"Water leaves the cells by osmosis through the partially permeable membrane."},{"prompt":"What happens to the mass?","choices":[{"text":"It decreases, because the potato loses water","correct":true,"feedback":"That completes the explanation."},{"text":"It increases","correct":false,"feedback":"Losing water means losing mass.","tag":"description_not_explanation"}],"reveal":"The mass decreases."}],"finalAnswer":"The solution is more concentrated than the cell contents (1), so water moves out of the potato cells by osmosis through the partially permeable membrane (1), so the mass decreases (1)."},"guided":[{"question":"A piece of potato has a mass of 2.50 g at the start and 2.80 g at the end. Calculate the percentage change in mass.","marks":2,"answer":{"type":"numeric","value":12,"tolerance":0.05,"unit":"%"},"hints":["Change = final − initial = 0.30 g.","Divide the change by the initial mass, then multiply by 100."],"solution":"0.30 ÷ 2.50 × 100 = 12%"}],"exam":[{"question":"Explain why percentage change in mass is calculated, rather than change in mass, in the potato osmosis practical.","marks":2,"answer":{"type":"extended"},"markScheme":[{"point":"The potato pieces may have different starting masses","marks":1},{"point":"Percentage change allows a fair comparison","marks":1}],"modelAnswer":"The pieces may not start with the same mass, so calculating percentage change lets the results be compared fairly.","mistakeTags":["description_not_explanation"]},{"question":"Red blood cells are placed in pure water. Explain what happens to them.","marks":3,"answer":{"type":"extended"},"markScheme":[{"point":"Water is more dilute than the cytoplasm / the cell contents are more concentrated","marks":1},{"point":"Water moves into the cells by osmosis through the partially permeable membrane","marks":1},{"point":"The cells swell and burst, because animal cells have no cell wall","marks":1}],"modelAnswer":"Pure water is more dilute than the cytoplasm, so water moves into the cells by osmosis through the partially permeable membrane. With no cell wall to resist it, the cells swell and burst.","mistakeTags":["missing_key_term","description_not_explanation"]}]}'::jsonb, 'published')
