  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('326f416f-8d40-56a3-86b8-ba286fba70e5', '{"style":"explanation","summary":"Explain evolution by natural selection as a sequence: variation, selection pressure, survival and reproduction of the best adapted, inheritance of alleles, and change over many generations.","knowledge":["Individuals in a population show variation, partly caused by mutations.","There is a selection pressure, such as a predator, disease or competition for food.","Individuals with characteristics best suited to the environment are more likely to survive and reproduce.","They pass their alleles to their offspring.","Over many generations the advantageous allele becomes more common in the population."],"vocabulary":[{"term":"Allele","meaning":"A version of a gene."},{"term":"Selection pressure","meaning":"A factor in the environment that affects which individuals survive."},{"term":"Mutation","meaning":"A change in DNA that can produce a new allele."}],"recognise":"Questions asking how a species ''evolved'', how bacteria became resistant, or why a characteristic became more common.","commandWords":[{"word":"Explain","meaning":"Give the steps in order, linking each one to the next."}],"method":[{"title":"Variation","detail":"Say the characteristic varies in the population, maybe because of a mutation."},{"title":"Selection pressure","detail":"Name what in the environment makes the characteristic useful."},{"title":"Survive and reproduce","detail":"Those with the characteristic are more likely to survive AND reproduce."},{"title":"Inheritance","detail":"They pass on the allele to their offspring."},{"title":"Over generations","detail":"The allele becomes more common in the population over many generations."}],"mistakes":[{"tag":"vague_language","text":"Saying the animal ''adapts to survive'' or ''needs'' the characteristic. Individuals don''t choose to change."},{"tag":"missing_key_term","text":"Forgetting ''reproduce'' and ''pass on alleles'' — survival alone doesn''t change the population."}],"worked":{"question":"Explain how peppered moths with dark wings became more common in industrial areas in the 1800s, when soot darkened tree bark. (4 marks)","marks":4,"steps":[{"prompt":"What is the first point?","choices":[{"text":"There was variation in wing colour, caused by a mutation","correct":true,"feedback":"Yes — start with variation."},{"text":"The moths turned dark to hide on the soot","correct":false,"feedback":"Individual moths can''t change their colour to match.","tag":"vague_language"}],"reveal":"Some moths had dark wings because of a mutation."},{"prompt":"What was the selection pressure?","choices":[{"text":"Birds could see pale moths more easily on dark bark and ate them","correct":true,"feedback":"Right: predation."},{"text":"The soot poisoned pale moths","correct":false,"feedback":"The pressure was being spotted by predators.","tag":"generic_knowledge"}],"reveal":"Pale moths were more visible to predatory birds."},{"prompt":"What happened next?","choices":[{"text":"Dark moths were more likely to survive and reproduce, passing on the allele for dark wings","correct":true,"feedback":"That''s the key link."},{"text":"Dark moths lived longer","correct":false,"feedback":"Survival alone isn''t enough: they must reproduce and pass on the allele.","tag":"missing_key_term"}],"reveal":"Dark moths survived, reproduced and passed on the dark allele."},{"prompt":"How do you finish?","choices":[{"text":"Over many generations, the dark allele became more common in the population","correct":true,"feedback":"That''s evolution."},{"text":"So all moths became dark straight away","correct":false,"feedback":"It happens over many generations.","tag":"vague_language"}],"reveal":"Over many generations the dark form became more common."}],"finalAnswer":"Variation from a mutation (1); birds ate pale moths that were easier to see on dark bark (1); dark moths more likely to survive and reproduce, passing on the allele (1); over many generations the allele became more common (1)."},"guided":[{"question":"Which of these is a selection pressure for bacteria developing antibiotic resistance?","marks":1,"answer":{"type":"choice","options":["Mutation","Use of antibiotics","Reproduction","Variation"],"correct":1},"hints":["A selection pressure is something in the environment that kills some individuals.","What kills non-resistant bacteria?"],"solution":"The use of antibiotics kills non-resistant bacteria, so it is the selection pressure."}],"exam":[{"question":"Explain how a population of bacteria can become resistant to an antibiotic.","marks":4,"answer":{"type":"extended"},"markScheme":[{"point":"A mutation produces a resistant bacterium / variation in resistance","marks":1},{"point":"The antibiotic kills non-resistant bacteria","marks":1},{"point":"Resistant bacteria survive and reproduce, passing on the resistance allele/gene","marks":1},{"point":"The resistant strain increases / becomes common over many generations","marks":1}],"modelAnswer":"A random mutation makes some bacteria resistant. When the antibiotic is used it kills the non-resistant bacteria, but the resistant ones survive and reproduce, passing on the resistance gene. Over many generations the resistant strain becomes common.","mistakeTags":["missing_key_term","vague_language"]}]}'::jsonb, 'published')
