  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('8c034930-a4d6-5ed4-a728-751f72f52c17', '{"style":"explanation","summary":"Explain ionic bonding as the transfer of electrons from a metal atom to a non-metal atom, forming oppositely charged ions held together by strong electrostatic attraction, and draw dot and cross diagrams.","knowledge":["Ionic bonding happens between a metal and a non-metal.","Metal atoms lose electrons to form positive ions; non-metal atoms gain electrons to form negative ions.","The ions have the electronic structure of a noble gas (a full outer shell).","Group 1 forms 1+ ions, group 2 forms 2+, group 6 forms 2−, group 7 forms 1−.","Oppositely charged ions are held together by strong electrostatic forces of attraction."],"vocabulary":[{"term":"Ion","meaning":"An atom or group of atoms with a charge, because it has lost or gained electrons."},{"term":"Electrostatic attraction","meaning":"The force between oppositely charged particles."}],"recognise":"A compound made of a metal and a non-metal, such as sodium chloride or magnesium oxide, with ''describe what happens'' or ''draw a dot and cross diagram''.","commandWords":[{"word":"Describe","meaning":"Say what happens to the electrons, step by step."},{"word":"Draw","meaning":"Show outer-shell electrons, ion charges in square brackets."}],"method":[{"title":"Identify the metal and non-metal","detail":"Use the periodic table to find their groups."},{"title":"Electrons transferred","detail":"Say how many electrons the metal loses and the non-metal gains."},{"title":"Ions formed","detail":"Give each ion''s charge and say they now have full outer shells."},{"title":"Attraction","detail":"Say the oppositely charged ions attract by strong electrostatic forces."}],"mistakes":[{"tag":"missing_key_term","text":"Saying electrons are ''shared'' — that''s covalent bonding."},{"tag":"vague_language","text":"Saying ''the atoms bond'' without explaining the electron transfer."}],"worked":{"question":"Describe what happens when magnesium reacts with oxygen to form magnesium oxide. Give the charges on the ions. (4 marks)","marks":4,"steps":[{"prompt":"What happens to the electrons?","choices":[{"text":"Magnesium transfers two electrons to oxygen","correct":true,"feedback":"Yes: magnesium is in group 2, oxygen in group 6."},{"text":"Magnesium and oxygen share two electrons","correct":false,"feedback":"Sharing is covalent. A metal and a non-metal transfer electrons.","tag":"missing_key_term"},{"text":"Oxygen transfers two electrons to magnesium","correct":false,"feedback":"Metals lose electrons; non-metals gain them.","tag":"vague_language"}],"reveal":"Each magnesium atom loses 2 electrons; each oxygen atom gains 2."},{"prompt":"What ions form?","choices":[{"text":"Mg²⁺ and O²⁻","correct":true,"feedback":"Correct — both now have the electronic structure of neon."},{"text":"Mg²⁻ and O²⁺","correct":false,"feedback":"Losing electrons gives a positive charge.","tag":"sign_error"},{"text":"Mg⁺ and O⁻","correct":false,"feedback":"Two electrons transfer, so the charges are 2+ and 2−.","tag":"arithmetic_slip"}],"reveal":"Mg²⁺ and O²⁻ ions form, each with a full outer shell."},{"prompt":"What holds the compound together?","choices":[{"text":"Strong electrostatic attraction between oppositely charged ions","correct":true,"feedback":"That''s the ionic bond."},{"text":"Weak forces between molecules","correct":false,"feedback":"Ionic compounds aren''t molecules: they form giant lattices.","tag":"missing_key_term"}],"reveal":"The ions are held together by strong electrostatic forces."}],"finalAnswer":"Magnesium loses two electrons (1), oxygen gains two electrons (1), forming Mg²⁺ and O²⁻ ions (1) which are held together by strong electrostatic attraction (1)."},"guided":[{"question":"What is the charge on a chloride ion?","marks":1,"answer":{"type":"choice","options":["1+","1−","2−","7−"],"correct":1},"hints":["Chlorine is in group 7.","It needs to gain one electron to fill its outer shell."],"solution":"Chlorine gains one electron, so the chloride ion is Cl⁻ (1−)."},{"question":"Give the formula of the ionic compound formed between calcium (Ca²⁺) and chloride ions (Cl⁻).","marks":1,"answer":{"type":"text","accept":["CaCl2","CaCl₂"]},"hints":["The charges must balance to zero.","You need two 1− ions to balance one 2+ ion."],"solution":"CaCl₂"}],"exam":[{"question":"Explain why sodium chloride has a high melting point.","marks":3,"answer":{"type":"extended"},"markScheme":[{"point":"Giant ionic lattice","marks":1},{"point":"Strong electrostatic forces between oppositely charged ions","marks":1},{"point":"A lot of energy is needed to overcome these forces","marks":1}],"modelAnswer":"Sodium chloride has a giant ionic lattice. There are strong electrostatic forces of attraction between the oppositely charged ions in all directions, so a lot of energy is needed to overcome them.","mistakeTags":["missing_key_term","vague_language"]}]}'::jsonb, 'published')
