  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('770ebd6e-7973-5686-9dc8-0b6b790e4129', '{"style":"calculation","summary":"Calculate relative formula mass (Mr) by adding the relative atomic masses of every atom in a formula, and use it to find the percentage by mass of an element in a compound.","knowledge":["Relative atomic mass (Ar) values are on the periodic table.","Mr is the sum of the Ar values of all the atoms in the formula.","A small number after a symbol multiplies that atom only; a number after a bracket multiplies everything inside.","Percentage by mass = (Ar × number of atoms of the element) ÷ Mr × 100."],"vocabulary":[{"term":"Relative atomic mass (Ar)","meaning":"The average mass of an atom of an element compared with 1/12 of a carbon-12 atom."},{"term":"Relative formula mass (Mr)","meaning":"The sum of the relative atomic masses of the atoms in a formula."}],"recognise":"Any question asking for Mr, ''relative formula mass'', or the percentage of an element in a compound.","commandWords":[{"word":"Calculate","meaning":"Show the sum of Ar values, then the answer."}],"method":[{"title":"Count the atoms","detail":"List each element and how many atoms of it are in the formula, expanding brackets."},{"title":"Multiply by Ar","detail":"Multiply each element''s Ar by its number of atoms."},{"title":"Add","detail":"Add the totals to get Mr. Mr has no units."}],"mistakes":[{"tag":"arithmetic_slip","text":"Applying a bracket''s number to only the first atom inside, e.g. Ca(OH)₂."},{"tag":"misread_question","text":"Using the atomic number instead of the relative atomic mass."}],"worked":{"question":"Calculate the relative formula mass of calcium hydroxide, Ca(OH)₂. (Ar: Ca = 40, O = 16, H = 1)","marks":2,"steps":[{"prompt":"How many of each atom are there?","choices":[{"text":"1 Ca, 2 O, 2 H","correct":true,"feedback":"The 2 multiplies everything in the bracket."},{"text":"1 Ca, 1 O, 2 H","correct":false,"feedback":"The bracket''s 2 applies to O as well as H.","tag":"arithmetic_slip"}],"reveal":"Ca × 1, O × 2, H × 2"},{"prompt":"Add up the masses.","choices":[{"text":"40 + (2 × 16) + (2 × 1) = 74","correct":true,"feedback":"Mr = 74."},{"text":"40 + 16 + 1 = 57","correct":false,"feedback":"You need to count each atom.","tag":"arithmetic_slip"}],"reveal":"Mr = 74"}],"finalAnswer":"Mr of Ca(OH)₂ = 74"},"guided":[{"question":"Calculate the Mr of carbon dioxide, CO₂. (C = 12, O = 16)","marks":1,"answer":{"type":"numeric","value":44},"hints":["There is 1 carbon and 2 oxygen atoms.","12 + 2 × 16"],"solution":"12 + 32 = 44"}],"exam":[{"question":"Calculate the percentage by mass of oxygen in magnesium carbonate, MgCO₃. (Mg = 24, C = 12, O = 16). Give your answer to the nearest whole number.","marks":3,"answer":{"type":"numeric","value":57,"tolerance":0.5,"unit":"%"},"markScheme":[{"point":"Mr = 24 + 12 + 48 = 84","marks":1},{"point":"48 ÷ 84 × 100","marks":1},{"point":"57%","marks":1}],"modelAnswer":"Mr = 84. Mass of oxygen = 3 × 16 = 48. 48 ÷ 84 × 100 = 57.1… ≈ 57%","mistakeTags":["arithmetic_slip","incomplete_method"]}]}'::jsonb, 'published')
