  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('91135b54-684c-5766-9543-69776f2500ce', '{"style":"explanation","summary":"Explain how temperature, concentration, pressure and surface area change the rate of a reaction, using collision theory: the frequency of collisions and the energy of particles.","knowledge":["Reactions happen when particles collide with energy greater than or equal to the activation energy.","Higher concentration or pressure: more particles in the same volume, so more frequent collisions.","Larger surface area (smaller pieces): more particles exposed, so more frequent collisions.","Higher temperature: particles move faster, so collide more often AND more collisions have enough energy to react.","Rate depends on the frequency of successful collisions."],"vocabulary":[{"term":"Activation energy","meaning":"The minimum energy colliding particles need to react."},{"term":"Successful collision","meaning":"A collision with enough energy to cause a reaction."}],"recognise":"A change in conditions (heating, more concentrated acid, powder instead of lumps) and ''explain the effect on the rate''.","commandWords":[{"word":"Explain","meaning":"Link the change to particles and collisions, then to rate."}],"method":[{"title":"Say what changes for the particles","detail":"More particles per volume, more exposed, or more energy."},{"title":"Say what happens to collisions","detail":"Use ''more frequent collisions'' — not just ''more collisions''."},{"title":"For temperature, add energy","detail":"More particles have energy ≥ activation energy."},{"title":"Conclude","detail":"So the rate of reaction increases."}],"mistakes":[{"tag":"vague_language","text":"Writing ''more collisions'' instead of ''more frequent collisions'' (collisions per second)."},{"tag":"missing_key_term","text":"For temperature, forgetting that more particles have at least the activation energy."}],"worked":{"question":"Explain why increasing the temperature increases the rate of reaction between magnesium and hydrochloric acid. (3 marks)","marks":3,"steps":[{"prompt":"What happens to the particles first?","choices":[{"text":"They gain kinetic energy and move faster","correct":true,"feedback":"Yes."},{"text":"There are more particles","correct":false,"feedback":"Heating doesn''t add particles; that''s concentration.","tag":"vague_language"}],"reveal":"The particles move faster."},{"prompt":"What does that do to collisions?","choices":[{"text":"Collisions are more frequent","correct":true,"feedback":"Right — more collisions per second."},{"text":"Collisions are bigger","correct":false,"feedback":"Use precise language: frequency and energy.","tag":"vague_language"}],"reveal":"More frequent collisions."},{"prompt":"What''s the second, more important effect?","choices":[{"text":"More collisions have energy greater than the activation energy","correct":true,"feedback":"That''s the mark many students miss."},{"text":"The activation energy decreases","correct":false,"feedback":"That''s what a catalyst does, not temperature.","tag":"missing_key_term"}],"reveal":"A greater proportion of collisions are successful."}],"finalAnswer":"Particles move faster (1) so collide more frequently (1), and more collisions have energy greater than or equal to the activation energy (1), so the rate increases."},"guided":[{"question":"Powdered calcium carbonate reacts faster with acid than lumps of the same mass. Which statement explains why?","marks":1,"answer":{"type":"choice","options":["Powder has a larger surface area to volume ratio, so collisions are more frequent","Powder has lower activation energy","Powder particles move faster","Powder contains more particles"],"correct":0},"hints":["The total mass is the same.","Think about how many particles are exposed to the acid."],"solution":"Powder has a larger surface area to volume ratio, so more particles are exposed and collisions are more frequent."}],"exam":[{"question":"Explain how increasing the concentration of an acid affects the rate of its reaction with zinc.","marks":3,"answer":{"type":"extended"},"markScheme":[{"point":"More acid particles in the same volume","marks":1},{"point":"More frequent collisions","marks":1},{"point":"Rate of reaction increases","marks":1}],"modelAnswer":"A more concentrated acid has more particles in the same volume, so collisions between acid particles and zinc are more frequent, and the rate increases.","mistakeTags":["vague_language","missing_key_term"]}]}'::jsonb, 'published')
on conflict (topic_id) do update set content = excluded.content, status = 'published', version = public.lessons.version + 1, updated_at = now()
  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('661561d7-da31-50f7-8de5-fa8f2eb710ef', '{"style":"calculation","summary":"Calculate speed using distance = speed × time, convert units, and explain the difference between speed (a scalar) and velocity (a vector).","knowledge":["distance travelled = speed × time (s = vt).","Speed is a scalar; velocity is speed in a given direction (a vector).","Typical speeds: walking about 1.5 m/s, cycling about 6 m/s, cars on a motorway about 30 m/s.","Convert km to m (× 1000) and minutes to seconds (× 60) before calculating in m/s."],"vocabulary":[{"term":"Scalar","meaning":"A quantity with size only, such as speed or distance."},{"term":"Vector","meaning":"A quantity with size and direction, such as velocity or displacement."}],"recognise":"Questions with a distance and a time, or asking for ''average speed''.","commandWords":[{"word":"Calculate","meaning":"Write the equation, substitute, then give the answer with units."},{"word":"Estimate","meaning":"Use typical values you know."}],"method":[{"title":"Write the equation","detail":"distance = speed × time, rearranged for what you need."},{"title":"Convert units","detail":"Use metres and seconds unless the question says otherwise."},{"title":"Substitute and calculate","detail":"Show the numbers in the equation."},{"title":"Give units","detail":"m/s for speed, m for distance, s for time."}],"mistakes":[{"tag":"unit_conversion","text":"Dividing kilometres by minutes and calling it m/s."},{"tag":"missing_units","text":"Leaving the unit off the answer."},{"tag":"rearranging_error","text":"Multiplying when you should divide: speed = distance ÷ time."}],"worked":{"question":"A cyclist travels 3.6 km in 10 minutes. Calculate her average speed in m/s. (3 marks)","marks":3,"steps":[{"prompt":"Convert the units first.","choices":[{"text":"3600 m and 600 s","correct":true,"feedback":"Both in SI units."},{"text":"3.6 m and 10 s","correct":false,"feedback":"Kilometres and minutes need converting.","tag":"unit_conversion"},{"text":"3600 m and 10 s","correct":false,"feedback":"Minutes need converting to seconds too.","tag":"unit_conversion"}],"reveal":"distance = 3600 m, time = 600 s"},{"prompt":"Choose the equation.","choices":[{"text":"speed = distance ÷ time","correct":true,"feedback":"Rearranged from s = vt."},{"text":"speed = distance × time","correct":false,"feedback":"That would give a huge number with the wrong units.","tag":"rearranging_error"}],"reveal":"speed = 3600 ÷ 600"},{"prompt":"Calculate.","choices":[{"text":"6 m/s","correct":true,"feedback":"A typical cycling speed — a good sense check."},{"text":"0.36 m/s","correct":false,"feedback":"You''ve divided the original numbers.","tag":"unit_conversion"}],"reveal":"speed = 6 m/s"}],"finalAnswer":"6 m/s"},"guided":[{"question":"A car travels at 25 m/s for 40 s. How far does it travel, in metres?","marks":2,"answer":{"type":"numeric","value":1000,"unit":"m"},"hints":["distance = speed × time","25 × 40"],"solution":"25 × 40 = 1000 m"}],"exam":[{"question":"A train travels 150 km in 1.25 hours. Calculate its average speed in m/s.","marks":3,"answer":{"type":"numeric","value":33.3,"tolerance":0.05,"unit":"m/s"},"markScheme":[{"point":"Converts to 150 000 m and 4500 s","marks":1},{"point":"150 000 ÷ 4500","marks":1},{"point":"33.3 m/s","marks":1}],"modelAnswer":"150 km = 150 000 m. 1.25 h = 4500 s. Speed = 150 000 ÷ 4500 = 33.3 m/s","mistakeTags":["unit_conversion","missing_units"]},{"question":"Explain why a car driving around a roundabout at a constant speed does not have a constant velocity.","marks":2,"answer":{"type":"extended"},"markScheme":[{"point":"Velocity is a vector / includes direction","marks":1},{"point":"The car''s direction is changing","marks":1}],"modelAnswer":"Velocity is speed in a given direction. On a roundabout the direction keeps changing, so the velocity changes even though the speed is constant.","mistakeTags":["missing_key_term"]}]}'::jsonb, 'published')
on conflict (topic_id) do update set content = excluded.content, status = 'published', version = public.lessons.version + 1, updated_at = now()
  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('9e9e71c8-892a-57c1-a4b8-37848bf84ac2', '{"style":"calculation","summary":"Calculate the kinetic energy of a moving object using Eₖ = ½mv², rearrange it to find mass or speed, and see why doubling speed quadruples kinetic energy.","knowledge":["Eₖ = ½ × m × v², with m in kg, v in m/s and Eₖ in joules (J).","Only the speed is squared, not the mass or the ½.","Doubling the speed makes the kinetic energy four times bigger.","To find v: v = √(2Eₖ ÷ m)."],"vocabulary":[{"term":"Kinetic energy store","meaning":"Energy an object has because it is moving."}],"recognise":"A moving object with a mass and a speed, or a question about energy when something speeds up or slows down.","commandWords":[{"word":"Calculate","meaning":"Write the equation, substitute, give the answer with units."}],"method":[{"title":"Convert","detail":"Mass in kg (g ÷ 1000), speed in m/s."},{"title":"Square the speed first","detail":"Work out v² before multiplying."},{"title":"Multiply by ½ and m","detail":"Give the answer in J."}],"mistakes":[{"tag":"wrong_formula","text":"Squaring the whole of ½mv rather than just v."},{"tag":"unit_conversion","text":"Using grams instead of kilograms."},{"tag":"incomplete_method","text":"Forgetting the square root when finding v."}],"worked":{"question":"A 1200 kg car travels at 15 m/s. Calculate its kinetic energy. (2 marks)","marks":2,"steps":[{"prompt":"What''s v²?","choices":[{"text":"225","correct":true,"feedback":"15² = 225."},{"text":"30","correct":false,"feedback":"Squaring isn''t doubling.","tag":"arithmetic_slip"}],"reveal":"v² = 225"},{"prompt":"Finish the calculation.","choices":[{"text":"½ × 1200 × 225 = 135 000 J","correct":true,"feedback":"Correct."},{"text":"1200 × 225 = 270 000 J","correct":false,"feedback":"Don''t forget the ½.","tag":"wrong_formula"}],"reveal":"Eₖ = 135 000 J"}],"finalAnswer":"135 000 J (135 kJ)"},"guided":[{"question":"A 0.5 kg ball is thrown at 8 m/s. Calculate its kinetic energy in joules.","marks":2,"answer":{"type":"numeric","value":16,"unit":"J"},"hints":["Square the speed: 8² = 64.","½ × 0.5 × 64"],"solution":"½ × 0.5 × 64 = 16 J"}],"exam":[{"question":"A 60 kg runner has 1920 J of kinetic energy. Calculate her speed.","marks":3,"answer":{"type":"numeric","value":8,"tolerance":0.01,"unit":"m/s"},"markScheme":[{"point":"v² = 2 × 1920 ÷ 60","marks":1},{"point":"v² = 64","marks":1},{"point":"v = 8 m/s","marks":1}],"modelAnswer":"v² = 2Eₖ ÷ m = 3840 ÷ 60 = 64, so v = 8 m/s","mistakeTags":["rearranging_error","incomplete_method"]}]}'::jsonb, 'published')
