  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('966ad7b2-df12-529c-8994-a86475fe7ca1', '{"style":"calculation","summary":"Use V = IR to calculate potential difference, current or resistance, and explain how increasing resistance reduces the current for the same potential difference.","knowledge":["potential difference (V) = current (A) × resistance (Ω).","For a fixed potential difference, a bigger resistance means a smaller current.","An ammeter is placed in series; a voltmeter is placed in parallel with the component.","Current in mA must be converted to A (÷ 1000)."],"vocabulary":[{"term":"Potential difference","meaning":"The energy transferred per unit charge between two points, measured in volts."},{"term":"Resistance","meaning":"How much a component opposes the current, measured in ohms (Ω)."}],"recognise":"Two of voltage, current and resistance are given and the third is asked for.","commandWords":[{"word":"Calculate","meaning":"Rearrange V = IR, substitute and give units."}],"method":[{"title":"Write V = IR","detail":"Then rearrange: I = V ÷ R or R = V ÷ I."},{"title":"Convert","detail":"mA to A, kΩ to Ω."},{"title":"Substitute and calculate","detail":"Give the unit: V, A or Ω."}],"mistakes":[{"tag":"rearranging_error","text":"Working out R = I ÷ V instead of V ÷ I."},{"tag":"unit_conversion","text":"Using milliamps as if they were amps."}],"worked":{"question":"A current of 0.5 A flows through a resistor with a potential difference of 6 V across it. Calculate its resistance. (2 marks)","marks":2,"steps":[{"prompt":"Rearrange V = IR for R.","choices":[{"text":"R = V ÷ I","correct":true,"feedback":"Correct."},{"text":"R = I ÷ V","correct":false,"feedback":"Divide both sides of V = IR by I.","tag":"rearranging_error"},{"text":"R = V × I","correct":false,"feedback":"That''s the power equation''s shape, not resistance.","tag":"wrong_formula"}],"reveal":"R = V ÷ I"},{"prompt":"Calculate.","choices":[{"text":"6 ÷ 0.5 = 12 Ω","correct":true,"feedback":"Yes."},{"text":"6 ÷ 0.5 = 3 Ω","correct":false,"feedback":"Dividing by 0.5 doubles the number.","tag":"arithmetic_slip"}],"reveal":"R = 12 Ω"}],"finalAnswer":"12 Ω"},"guided":[{"question":"A 9 V battery is connected to a 45 Ω resistor. Calculate the current in amps.","marks":2,"answer":{"type":"numeric","value":0.2,"unit":"A"},"hints":["I = V ÷ R","9 ÷ 45"],"solution":"I = 9 ÷ 45 = 0.2 A"}],"exam":[{"question":"A current of 250 mA flows through a lamp of resistance 24 Ω. Calculate the potential difference across the lamp.","marks":3,"answer":{"type":"numeric","value":6,"unit":"V"},"markScheme":[{"point":"Converts 250 mA to 0.25 A","marks":1},{"point":"V = 0.25 × 24","marks":1},{"point":"6 V","marks":1}],"modelAnswer":"I = 0.25 A. V = IR = 0.25 × 24 = 6 V","mistakeTags":["unit_conversion","missing_units"]}]}'::jsonb, 'published')
