  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('91fc53ea-2994-5bc9-abe9-7921aa760cde', '{"style":"analysis","summary":"Zoom in on single words and explore their connotations — the ideas and feelings they suggest — so you can explain precisely how a writer''s word choices affect the reader.","knowledge":["Denotation is a word''s literal meaning; connotation is what it suggests.","Strong verbs, adjectives and adverbs often carry the most meaning.","Explain what the word suggests, then how it makes the reader feel or think.","One well-chosen word, closely analysed, is worth more than a long quotation."],"vocabulary":[{"term":"Connotation","meaning":"An idea or feeling a word suggests beyond its literal meaning."},{"term":"Verb","meaning":"An action or state word — often where the energy of a sentence is."}],"recognise":"Questions that ask ''how does the writer use language…'' or point you to specific lines.","commandWords":[{"word":"How does the writer…","meaning":"Explain the methods and their effects — not just what happens."},{"word":"Analyse","meaning":"Pick apart the words and explain how they create meaning."}],"method":[{"title":"Choose a powerful word","detail":"Look for verbs and adjectives that do more than describe."},{"title":"Unpack its connotations","detail":"Ask: what does this word make me think of?"},{"title":"Link to the effect","detail":"Say what the reader feels or understands because of it."},{"title":"Link to the bigger picture","detail":"Connect the effect to the mood or the writer''s purpose."}],"mistakes":[{"tag":"technique_spotting","text":"Writing ''the writer uses a verb to create imagery'' — which says nothing about this word."},{"tag":"quotation_too_long","text":"Quoting a whole sentence instead of the key word."},{"tag":"no_effect_on_reader","text":"Explaining what the word means but not its effect."}],"worked":{"question":"Read this extract:\n\n“The wind came first, hurling itself at the windows like something that had been locked out too long. Then the rain: not falling, but thrown, in fistfuls, rattling the glass. Inside, the candle flinched. Mara pressed her back to the cold wall and listened to the old house groan, its beams creaking like the bones of a tired giant.”\n\nHow does the writer use language to make the storm seem threatening?","marks":4,"steps":[{"prompt":"Which word is the most powerful one to analyse?","choices":[{"text":"\"hurling\"","correct":true,"feedback":"Good choice — a violent verb you can explore in detail."},{"text":"\"windows\"","correct":false,"feedback":"A plain noun; there''s little to analyse.","tag":"no_evidence"},{"text":"The whole first sentence","correct":false,"feedback":"Too long: you won''t be able to analyse it closely.","tag":"quotation_too_long"}],"reveal":"Focus word: \"hurling\"."},{"prompt":"What does \"hurling\" suggest?","choices":[{"text":"Deliberate, aggressive force, as if the wind is attacking","correct":true,"feedback":"Yes — the wind seems to throw itself with intent."},{"text":"That it was windy","correct":false,"feedback":"That''s the literal meaning — go further.","tag":"no_effect_on_reader"},{"text":"It is a verb","correct":false,"feedback":"Naming the word class isn''t analysis.","tag":"technique_spotting"}],"reveal":"\"Hurling\" suggests violent, deliberate force, as if the wind is attacking the house."},{"prompt":"Now link it to the reader and the rest of the extract.","choices":[{"text":"The reader feels the house is under attack, which builds through the rain being ''thrown'' — the storm seems alive and hostile","correct":true,"feedback":"Excellent: effect, plus a link to a related word."},{"text":"This makes it interesting for the reader","correct":false,"feedback":"Too vague — what does the reader feel, and why?","tag":"no_effect_on_reader"}],"reveal":"The reader feels the house is besieged; together with the rain being ''thrown'', the storm seems alive and hostile."}],"finalAnswer":"The writer presents the storm as an attacker. The verb \"hurling\" suggests violent, deliberate force, as though the wind is throwing itself at the house. This makes the reader feel the characters are under siege, an idea reinforced when the rain is \"thrown, in fistfuls\", as if the storm is a living enemy."},"guided":[{"question":"In the extract, the candle \"flinched\". Which effect does this word create best?","marks":1,"answer":{"type":"choice","options":["It shows the candle was badly made","It personifies the candle as frightened, reflecting Mara''s fear","It shows the room was bright","It shows it was night"],"correct":1},"hints":["Who usually flinches?","If an object reacts like a frightened person, what does that suggest about the mood?"],"solution":"Personification: the candle reacts like a frightened person, mirroring Mara''s fear."}],"exam":[{"question":"Using the extract, write a paragraph analysing how the writer presents the house in the final sentence (\"Inside, the candle flinched… tired giant\").","marks":4,"answer":{"type":"extended"},"markScheme":[{"point":"Makes a clear point about how the house is presented (e.g. old, weak, alive)","marks":1},{"point":"Uses a short, well-chosen quotation (e.g. \"groan\", \"bones of a tired giant\")","marks":1},{"point":"Explores the connotations of specific words","marks":1},{"point":"Explains the effect on the reader / links to the mood of the extract","marks":1}],"modelAnswer":"The writer presents the house as old and vulnerable. The verb \"groan\" personifies it as if it is in pain under the storm''s attack, and the simile \"like the bones of a tired giant\" suggests something huge but worn out, close to collapse. This makes the reader worry that the house — Mara''s only shelter — may not survive, increasing the tension.","mistakeTags":["technique_spotting","no_effect_on_reader","quotation_too_long"]}]}'::jsonb, 'published')
