  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('e784b311-19a1-5640-bfb2-22a72af5a41c', '{"style":"analysis","summary":"Build analytical paragraphs in three moves: WHAT the writer is doing, HOW they do it (with evidence and a method), and WHY — the effect on the reader and the writer''s purpose.","knowledge":["WHAT: a clear point that answers the question.","HOW: short evidence plus the method, analysed closely.","WHY: the effect on the reader and the writer''s purpose.","Each paragraph should go deeper than the last, not just add another example."],"vocabulary":[{"term":"Topic sentence","meaning":"The opening sentence that states the paragraph''s point."}],"recognise":"Any analysis question in English Language or Literature.","commandWords":[{"word":"How","meaning":"Focus on methods and effects, not retelling the story."}],"method":[{"title":"What","detail":"Start with a point that uses the question''s words."},{"title":"How","detail":"Embed a short quotation and name the method if it helps."},{"title":"Zoom in","detail":"Analyse one or two words in detail."},{"title":"Why","detail":"Explain the effect on the reader and why the writer wanted it."}],"mistakes":[{"tag":"not_linked_to_question","text":"A point that doesn''t answer the question asked."},{"tag":"description_not_explanation","text":"Retelling what happens instead of analysing how."},{"tag":"no_effect_on_reader","text":"Stopping after the evidence."}],"worked":{"question":"Using the storm extract (“The wind came first, hurling itself at the windows like some…”), build a paragraph answering: How does the writer create tension?","marks":4,"steps":[{"prompt":"Choose the best WHAT (topic sentence).","choices":[{"text":"The writer creates tension by presenting the storm as a violent intruder trying to get in.","correct":true,"feedback":"Clear, uses the question''s word ''tension'', and sets up the analysis."},{"text":"In this extract there is a storm and Mara is inside.","correct":false,"feedback":"This retells events rather than making a point.","tag":"description_not_explanation"},{"text":"The writer uses lots of techniques.","correct":false,"feedback":"Too vague to analyse.","tag":"not_linked_to_question"}],"reveal":"WHAT: The writer creates tension by presenting the storm as a violent intruder trying to get in."},{"prompt":"Choose the best HOW.","choices":[{"text":"The simile \"like something that had been locked out too long\" makes the wind seem desperate to get inside.","correct":true,"feedback":"Short evidence, method and a precise interpretation."},{"text":"The writer says \"The wind came first, hurling itself at the windows like something that had been locked out too long.\"","correct":false,"feedback":"Too long and no analysis yet.","tag":"quotation_too_long"}],"reveal":"HOW: The simile \"like something that had been locked out too long\" makes the wind seem desperate to get in."},{"prompt":"Choose the best WHY.","choices":[{"text":"This makes the reader fear what will happen if it breaks in, so we share Mara''s sense of being trapped.","correct":true,"feedback":"Effect on the reader, linked to the character."},{"text":"This is effective.","correct":false,"feedback":"Say what it does to the reader.","tag":"no_effect_on_reader"}],"reveal":"WHY: The reader fears what will happen if it gets in, sharing Mara''s sense of being trapped."}],"finalAnswer":"The writer creates tension by presenting the storm as a violent intruder. The simile \"like something that had been locked out too long\" suggests the wind is desperate, even resentful, as if it has a right to come in. This makes the reader fear what will happen if it breaks through, so we share Mara''s sense of being trapped."},"guided":[{"question":"Which part of a WHAT-HOW-WHY paragraph is this? “This makes the reader feel uneasy, because the storm seems to have a will of its own.”","marks":1,"answer":{"type":"choice","options":["What","How","Why"],"correct":2},"hints":["Is it the point, the evidence, or the effect?","It talks about the reader."],"solution":"It''s the WHY: the effect on the reader."}],"exam":[{"question":"Write one WHAT-HOW-WHY paragraph about how the writer presents Mara in the storm extract.","marks":6,"answer":{"type":"extended"},"markScheme":[{"point":"WHAT: a clear point about Mara (e.g. frightened, isolated, vulnerable)","marks":1},{"point":"HOW: short, embedded evidence (e.g. \"pressed her back to the cold wall\")","marks":1},{"point":"Analysis of specific word choices","marks":2},{"point":"WHY: effect on the reader","marks":1},{"point":"Links to the writer''s purpose or the wider extract","marks":1}],"modelAnswer":"Mara is presented as vulnerable and alone. She \"pressed her back to the cold wall\", which suggests she is retreating as far as possible from the storm; the adjective \"cold\" shows even the house offers no comfort. The reader feels protective of her, and because she only \"listened\", she seems powerless against the storm''s noise — the writer builds tension by keeping her passive while the storm acts.","mistakeTags":["description_not_explanation","no_effect_on_reader","weak_structure"]}]}'::jsonb, 'published')
