  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('13155c29-d435-525c-b8b2-0f9c27b31aa6', '{"style":"evaluation","summary":"Write a convincing argument: a clear viewpoint from the first line, logically ordered paragraphs, evidence, a counter-argument you knock down, and an ending that stays with the reader.","knowledge":["Decide your view before you plan — and stick to it.","Each paragraph makes one point, supported by evidence or an example.","A counter-argument and rebuttal makes your argument stronger, not weaker.","Match tone and form to the audience: an article reads differently from a speech.","Accuracy and varied sentences are marked too."],"vocabulary":[{"term":"Rebuttal","meaning":"Showing why an opposing argument is weaker than yours."},{"term":"Discourse marker","meaning":"Words that guide the reader, such as ''furthermore'' or ''however''."}],"recognise":"A statement to respond to, with a form (article, letter, speech, essay) and an audience.","commandWords":[{"word":"Write… arguing/explaining your point of view","meaning":"Take a clear position and support it."}],"method":[{"title":"Decode the task","detail":"Underline the form, audience and purpose."},{"title":"Plan 4–5 points","detail":"Order them so the strongest comes last, with a counter-argument before it."},{"title":"Hook","detail":"Open with an anecdote, a striking fact or a bold statement."},{"title":"Develop","detail":"Each paragraph: point, evidence, why it matters."},{"title":"End strongly","detail":"Return to your opening or call the reader to act."}],"mistakes":[{"tag":"weak_structure","text":"Listing points without an order or links between them."},{"tag":"one_sided","text":"Ignoring the other side, so the argument seems naive."},{"tag":"spag_errors","text":"Comma splices and missing apostrophes — save time to proofread."}],"worked":{"question":"''Homework should be banned for all secondary school students.'' Write an article for a newspaper in which you argue for or against this statement.","marks":40,"steps":[{"prompt":"Which opening is the strongest hook?","choices":[{"text":"It''s 10.47pm. Sam has finished his third worksheet of the night, and his eyes are closing over a page he no longer understands.","correct":true,"feedback":"An anecdote puts the reader in the situation straight away."},{"text":"In this article I am going to argue about homework.","correct":false,"feedback":"Announcing what you''ll do wastes your opening.","tag":"weak_structure"}],"reveal":"Open with a short anecdote."},{"prompt":"Where should the counter-argument go?","choices":[{"text":"Just before your strongest point, so you can rebut it and finish on strength","correct":true,"feedback":"Yes — acknowledge, rebut, then land your best point."},{"text":"Leave it out — it weakens your case","correct":false,"feedback":"Ignoring it makes your argument seem one-sided.","tag":"one_sided"}],"reveal":"Counter-argument and rebuttal come before the final point."},{"prompt":"Which ending is strongest?","choices":[{"text":"Return to Sam: imagine him asleep by ten, ready to learn tomorrow. That''s the school day we should be fighting for.","correct":true,"feedback":"A cyclical ending ties the piece together."},{"text":"In conclusion, that is why homework should be banned.","correct":false,"feedback":"Flat: it repeats rather than persuades.","tag":"weak_structure"}],"reveal":"End by returning to the opening image with a call to action."}],"finalAnswer":"Plan: anecdote hook → point 1 (wellbeing) → point 2 (inequality of home support) → counter-argument (practice matters) and rebuttal (practice works better in school) → strongest point (rest improves learning) → cyclical ending with a call to action."},"guided":[{"question":"Which sentence is the best rebuttal of ''Homework helps students practise''?","marks":1,"answer":{"type":"choice","options":["Practice is boring.","Of course practice matters — but it works best in lessons, where a teacher can spot mistakes before they become habits.","Homework is bad.","Some people like homework."],"correct":1},"hints":["A rebuttal accepts part of the point, then shows why it doesn''t win.","Look for ''but'' with a reason."],"solution":"The second option concedes the point and then gives a reason it doesn''t justify homework."}],"exam":[{"question":"''Young people spend too much time on their phones.'' Write the opening two paragraphs of a speech to your year group arguing your view.","marks":8,"answer":{"type":"extended"},"markScheme":[{"point":"Clear viewpoint established early","marks":1},{"point":"Engaging hook suited to a speech (direct address, anecdote, question)","marks":2},{"point":"A developed point with evidence or example","marks":2},{"point":"Tone and register suit the audience","marks":1},{"point":"Varied sentences and accurate spelling and punctuation","marks":2}],"modelAnswer":"Hands up if you checked your phone before you''d even got out of bed this morning. Look around — that''s most of us. I''m not here to tell you phones are evil; I''m here to ask who''s really in charge.\n\nEvery app on your screen was designed by people whose job is to keep you scrolling. The longer you stay, the more they earn. So when you lose an evening to videos you won''t remember tomorrow, that isn''t a lack of willpower — it''s a business plan working exactly as intended.","mistakeTags":["weak_structure","spag_errors","one_sided"]}]}'::jsonb, 'published')
