  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('4e9d5446-ccd0-57aa-aa46-b29920762352', '{"style":"evaluation","summary":"Open every literature essay with a thesis: a one- or two-sentence argument that answers the question, names the writer''s purpose and gives your essay a direction to follow.","knowledge":["A thesis answers the question directly — it''s an argument, not a summary.","Good theses mention the writer and what they wanted the audience to think.","Each paragraph should prove part of the thesis.","Words like ''ultimately'', ''initially… but'' and ''Dickens uses… to'' help build a developing argument."],"vocabulary":[{"term":"Thesis","meaning":"The central argument of your essay."}],"recognise":"Any essay question: ''How does the writer present…'', ''Explore how…''.","commandWords":[{"word":"Explore","meaning":"Consider more than one idea or interpretation."}],"method":[{"title":"Find the key word","detail":"Underline the character or theme in the question."},{"title":"Decide what the writer wants us to think","detail":"What is the writer''s message about it?"},{"title":"Show development","detail":"How does the character or theme change across the text?"},{"title":"Write it in two sentences","detail":"Then plan paragraphs that each prove a part of it."}],"mistakes":[{"tag":"description_not_explanation","text":"A thesis that summarises the plot."},{"tag":"not_linked_to_question","text":"A thesis about the whole text rather than the question''s focus."}],"worked":{"question":"How does Dickens present Scrooge as a character who changes in ''A Christmas Carol''?","marks":4,"steps":[{"prompt":"Which is the best thesis?","choices":[{"text":"Dickens presents Scrooge''s transformation from isolated miser to generous member of society to show his Victorian readers that anyone can change — and that the wealthy have a duty to.","correct":true,"feedback":"An argument, with the writer''s purpose and context."},{"text":"Scrooge is mean at the start and nice at the end.","correct":false,"feedback":"A plot summary, not an argument.","tag":"description_not_explanation"},{"text":"Dickens uses lots of language techniques to present Scrooge.","correct":false,"feedback":"This gives the essay no direction.","tag":"not_linked_to_question"}],"reveal":"Thesis chosen."},{"prompt":"Which paragraph plan best follows the thesis?","choices":[{"text":"1. Scrooge''s isolation in Stave 1 → 2. the ghosts force him to see the poor → 3. his generosity in Stave 5 as Dickens''s model for readers","correct":true,"feedback":"Each paragraph proves a stage of the change."},{"text":"1. Similes → 2. Metaphors → 3. Adjectives","correct":false,"feedback":"Organising by technique loses the argument.","tag":"weak_structure"}],"reveal":"Plan: isolation → confrontation → redemption."}],"finalAnswer":"Thesis: Dickens presents Scrooge''s transformation from isolated miser to generous member of society to show his readers that anyone can change, and that the wealthy have a responsibility to. Plan: isolation (Stave 1) → confrontation with poverty (Staves 2–4) → redemption (Stave 5)."},"guided":[{"question":"Which word makes a thesis sound like an argument rather than a description?","marks":1,"answer":{"type":"choice","options":["happens","to show","then","also"],"correct":1},"hints":["An argument explains the writer''s purpose.","Look for the phrase that introduces a reason."],"solution":"''To show'' introduces the writer''s purpose."}],"exam":[{"question":"Write a thesis statement for: ''How does Shakespeare present ambition in Macbeth?''","marks":4,"answer":{"type":"extended"},"markScheme":[{"point":"Answers the question directly (about ambition)","marks":1},{"point":"Presents an argument rather than a summary","marks":1},{"point":"Refers to Shakespeare''s purpose or message","marks":1},{"point":"Suggests development or more than one interpretation","marks":1}],"modelAnswer":"Shakespeare presents ambition as a force that begins as a private desire but grows into a destructive obsession, warning his Jacobean audience that ambition which defies the natural order leads only to guilt, isolation and death.","mistakeTags":["description_not_explanation","no_context_link"]}]}'::jsonb, 'published')
on conflict (topic_id) do update set content = excluded.content, status = 'published', version = public.lessons.version + 1, updated_at = now()
  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('5ede6902-b9be-5494-9d10-d4bb6db6ec3b', '{"style":"analysis","summary":"Explore how Shakespeare presents ambition as the force that drives Macbeth to murder, and how it destroys him and Lady Macbeth — with short quotations and context about the divine right of kings.","knowledge":["Macbeth''s ambition is awakened by the witches'' prophecy and pushed by Lady Macbeth.","In Act 1 he admits his ambition is \"vaulting\" and has no other spur — he has no good reason to kill Duncan.","He hides his \"black and deep desires\" — ambition is shown as dark and secret.","Jacobean audiences believed kings were chosen by God; killing one broke the natural order.","By the end, ambition leaves Macbeth isolated and seeing life as meaningless."],"vocabulary":[{"term":"Tragic hero","meaning":"A great character whose flaw leads to their downfall."},{"term":"Hamartia","meaning":"The fatal flaw of a tragic hero — here, ambition."},{"term":"Divine right of kings","meaning":"The belief that monarchs are appointed by God."}],"recognise":"Questions on ambition, power, Macbeth''s or Lady Macbeth''s character, or the extract around Act 1 scenes 3–7.","commandWords":[{"word":"Starting with this extract, explore…","meaning":"Analyse the extract, then link to the whole play."}],"method":[{"title":"Thesis","detail":"Ambition as a destructive force that breaks the natural order."},{"title":"Extract","detail":"Analyse two or three short quotations closely."},{"title":"Whole play","detail":"Trace how ambition changes Macbeth and Lady Macbeth."},{"title":"Context","detail":"Link to the divine right of kings and James I."}],"mistakes":[{"tag":"no_context_link","text":"Mentioning context in a separate paragraph instead of linking it to the analysis."},{"tag":"quotation_too_long","text":"Copying out long speeches rather than picking key words."},{"tag":"description_not_explanation","text":"Retelling the plot."}],"worked":{"question":"Macbeth says: \"I have no spur / To prick the sides of my intent, but only / Vaulting ambition, which o''erleaps itself / And falls on th''other.\" How does Shakespeare present ambition here?","marks":6,"steps":[{"prompt":"What is Macbeth admitting?","choices":[{"text":"He has no good reason to kill Duncan — only his ambition","correct":true,"feedback":"Yes: the ''spur'' that should drive him is missing."},{"text":"He is going to ride a horse","correct":false,"feedback":"The horse riding is a metaphor.","tag":"description_not_explanation"}],"reveal":"Macbeth admits ambition is his only motive."},{"prompt":"Which word is best to analyse?","choices":[{"text":"\"Vaulting\"","correct":true,"feedback":"It suggests leaping too high."},{"text":"\"I\"","correct":false,"feedback":"Pick a word with rich connotations.","tag":"no_evidence"}],"reveal":"\"Vaulting\" suggests a rider leaping too high over an obstacle."},{"prompt":"What''s the best analysis and context link?","choices":[{"text":"Like a rider who jumps too far and falls, ambition will cause Macbeth''s downfall — foreshadowing that overreaching against God''s chosen king will be punished.","correct":true,"feedback":"Analysis, foreshadowing and context, all linked."},{"text":"Shakespeare uses a metaphor. In Jacobean times people believed in kings.","correct":false,"feedback":"Technique-spotting and bolted-on context.","tag":"no_context_link"}],"reveal":"Ambition is presented as self-destructive, foreshadowing his fall."}],"finalAnswer":"Shakespeare presents ambition as self-destructive. Macbeth admits he has no \"spur\" except \"vaulting ambition\", picturing a rider who leaps so high he \"falls on th''other\" side. This foreshadows his downfall, warning a Jacobean audience that overreaching against a king chosen by God breaks the natural order and will be punished."},"guided":[{"question":"Which belief would make a Jacobean audience see Duncan''s murder as especially shocking?","marks":1,"answer":{"type":"choice","options":["The divine right of kings","Democracy","Germ theory","The Poor Law"],"correct":0},"hints":["Who did people think chose the king?","Killing the king was like going against God."],"solution":"The divine right of kings: killing Duncan was a crime against God''s order."}],"exam":[{"question":"How does Shakespeare present the consequences of ambition in Macbeth? Write about the play as a whole.","marks":12,"answer":{"type":"extended"},"markScheme":[{"point":"A clear argument (thesis) about the consequences of ambition","marks":2},{"point":"Well-chosen, short quotations from across the play","marks":2},{"point":"Close analysis of language and its effects","marks":3},{"point":"Dramatic methods (e.g. soliloquy, structure, foreshadowing)","marks":2},{"point":"Context linked to the analysis (e.g. divine right, Jacobean beliefs)","marks":2},{"point":"Coherent structure and accurate writing","marks":1}],"modelAnswer":"Shakespeare presents ambition as leading to guilt, isolation and despair. Early on, Macbeth''s ambition makes him hide his \"black and deep desires\", showing it as something shameful. After the murder, guilt fills him with visions and sleeplessness — Macbeth \"does murder sleep\". Lady Macbeth''s ambition collapses into the sleepwalking scene, where she cannot wash out the \"damned spot\". By Act 5, Macbeth sees life as \"a tale told by an idiot\": his ambition has destroyed all meaning. For a Jacobean audience who believed in the divine right of kings, this downfall shows the natural order being restored.","mistakeTags":["no_context_link","description_not_explanation","weak_structure"]}]}'::jsonb, 'published')
on conflict (topic_id) do update set content = excluded.content, status = 'published', version = public.lessons.version + 1, updated_at = now()
  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('6495f71f-8a77-578c-9f46-413d6cb51a5c', '{"style":"analysis","summary":"Explore how Priestley uses An Inspector Calls to argue for collective social responsibility, contrasting the older Birlings'' selfishness with the younger generation''s capacity to change.","knowledge":["Each Birling contributes to Eva Smith''s death; no single person is entirely to blame — that''s the point.","The Inspector acts as Priestley''s voice, arguing that we are all responsible for each other.","Mr and Mrs Birling refuse to accept responsibility; Sheila and Eric are changed by the evening.","The play is set in 1912 but was first performed in 1945, when Britain was building the welfare state.","The final phone call means the Birlings cannot escape the lesson."],"vocabulary":[{"term":"Collective responsibility","meaning":"The idea that society shares responsibility for how its members are treated."},{"term":"Dramatic irony","meaning":"When the audience knows something the characters don''t."},{"term":"Mouthpiece","meaning":"A character who expresses the writer''s views."}],"recognise":"Questions on responsibility, the Inspector, class, generations, or how Priestley presents a Birling.","commandWords":[{"word":"How does Priestley present…","meaning":"Focus on Priestley''s methods and message."}],"method":[{"title":"Thesis","detail":"Priestley contrasts those who accept and refuse responsibility to persuade his 1945 audience."},{"title":"Older generation","detail":"Show how Mr and Mrs Birling deny responsibility."},{"title":"Younger generation","detail":"Show how Sheila and Eric change."},{"title":"Methods","detail":"Dramatic irony, the Inspector''s role, the ending."},{"title":"Context","detail":"1912 setting vs 1945 audience."}],"mistakes":[{"tag":"description_not_explanation","text":"Retelling each Birling''s involvement in order."},{"tag":"no_context_link","text":"Forgetting the 1912/1945 contrast."},{"tag":"not_linked_to_question","text":"Writing about characters without linking back to responsibility."}],"worked":{"question":"How does Priestley use Mr Birling to present ideas about responsibility?","marks":6,"steps":[{"prompt":"What''s the strongest point to start with?","choices":[{"text":"Priestley makes Mr Birling''s rejection of social responsibility look foolish, so the audience rejects his views too.","correct":true,"feedback":"An argument about Priestley''s purpose."},{"text":"Mr Birling is a businessman who sacked Eva Smith.","correct":false,"feedback":"That''s plot, not an argument.","tag":"description_not_explanation"}],"reveal":"Point: Priestley makes Birling''s views look foolish."},{"prompt":"Which method best supports this?","choices":[{"text":"Dramatic irony: Birling confidently predicts there will be no war and calls the Titanic unsinkable, which the 1945 audience knows is wrong.","correct":true,"feedback":"If he is wrong about these, the audience doubts his views on responsibility too."},{"text":"He has a lot of lines.","correct":false,"feedback":"Not a meaningful method.","tag":"technique_spotting"}],"reveal":"Dramatic irony undermines Birling."},{"prompt":"How do you link to context?","choices":[{"text":"Watching in 1945, after two world wars, the audience is encouraged to reject Birling''s selfish capitalism and support a fairer society.","correct":true,"feedback":"Context woven into the purpose."},{"text":"Priestley was born in 1894.","correct":false,"feedback":"A fact that isn''t linked to the question.","tag":"no_context_link"}],"reveal":"Context: the 1945 audience."}],"finalAnswer":"Priestley uses dramatic irony to make Mr Birling''s rejection of social responsibility look foolish. His confident predictions that there will be no war and that the Titanic is unsinkable are known to be wrong by the 1945 audience, so they also doubt his insistence that a man should look after only himself and his family. After two world wars, Priestley encourages his audience to reject Birling''s selfish capitalism."},"guided":[{"question":"When was An Inspector Calls first performed?","marks":1,"answer":{"type":"choice","options":["1912","1945","1918","1960"],"correct":1},"hints":["It''s set before the First World War…","…but first performed just after the Second."],"solution":"1945, though it is set in 1912."}],"exam":[{"question":"How does Priestley present Sheila as a character who learns to accept responsibility?","marks":12,"answer":{"type":"extended"},"markScheme":[{"point":"Clear thesis about Sheila''s development and Priestley''s purpose","marks":2},{"point":"Evidence from the start and end of the play","marks":2},{"point":"Analysis of language and dramatic methods (stage directions, contrast with her parents)","marks":3},{"point":"Links to the theme of responsibility and generations","marks":2},{"point":"Context woven in (1912/1945, gender, class)","marks":2},{"point":"Coherent structure and accurate writing","marks":1}],"modelAnswer":"Priestley presents Sheila''s journey from a sheltered, privileged girl to someone who accepts her share of responsibility, making her a model for his audience. At first her concerns are trivial and she is excited by Gerald''s ring. When she learns how her jealousy cost Eva her job at the shop, she is genuinely ashamed and promises never to act that way again. By the end she refuses to pretend nothing has happened, unlike her parents, and the contrast suggests Priestley''s hope lies with the young. For a 1945 audience, Sheila shows that people — and women in particular — can challenge the attitudes of their elders.","mistakeTags":["description_not_explanation","no_context_link","not_linked_to_question"]}]}'::jsonb, 'published')
on conflict (topic_id) do update set content = excluded.content, status = 'published', version = public.lessons.version + 1, updated_at = now()
  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('79290937-aa50-502a-bb83-39fe56fc79b7', '{"style":"evaluation","summary":"Use a source''s provenance — its nature, origin and purpose — to judge how useful and reliable it is, instead of only describing what it shows.","knowledge":["Nature: what type of source it is (a speech, diary, poster, photograph, government report).","Origin: who made it and when.","Purpose: why it was made and who it was for.","A biased source can still be useful — it shows what its author wanted people to think.","Combine provenance with content and your own knowledge."],"vocabulary":[{"term":"Provenance","meaning":"Where a source comes from: its nature, origin and purpose."},{"term":"Utility","meaning":"How useful a source is for a particular enquiry."},{"term":"Propaganda","meaning":"Material designed to persuade people to believe something."}],"recognise":"''How useful is Source A for an enquiry into…?'' or ''How reliable…?''","commandWords":[{"word":"How useful","meaning":"Weigh what the source can and can''t tell you about the enquiry."},{"word":"Explain your answer using Source A and your own knowledge","meaning":"Use both the source and facts you know."}],"method":[{"title":"Content","detail":"What does the source tell you about the enquiry?"},{"title":"Provenance","detail":"How do its nature, origin and purpose affect its usefulness?"},{"title":"Own knowledge","detail":"Does what you know support or challenge it?"},{"title":"Judgement","detail":"Conclude how useful it is FOR THIS ENQUIRY."}],"mistakes":[{"tag":"source_content_only","text":"Describing what the source shows without discussing who made it and why."},{"tag":"generic_knowledge","text":"Writing ''it''s biased so it''s not useful'' — bias can make it useful."},{"tag":"no_judgement","text":"Not concluding how useful it is."}],"worked":{"question":"Source A is a Nazi election poster from 1932 showing unemployed workers with the slogan ''Our last hope: Hitler''. How useful is Source A for an enquiry into why the Nazis gained support?","marks":8,"steps":[{"prompt":"What does the content suggest?","choices":[{"text":"The Nazis targeted the unemployed, promising hope during the Depression","correct":true,"feedback":"Specific and linked to the enquiry."},{"text":"It shows some people","correct":false,"feedback":"Be specific and link to the enquiry.","tag":"generic_knowledge"}],"reveal":"Content: the Nazis appealed to the desperate unemployed."},{"prompt":"How does provenance affect its usefulness?","choices":[{"text":"As Nazi propaganda from 1932, it shows the message the Nazis used to win votes, though not whether voters believed it","correct":true,"feedback":"Uses purpose to show both value and limits."},{"text":"It''s propaganda, so it''s useless","correct":false,"feedback":"Propaganda is very useful for showing a party''s methods.","tag":"generic_knowledge"}],"reveal":"Provenance: useful for Nazi methods, limited on voters'' motives."},{"prompt":"Which own knowledge supports it?","choices":[{"text":"Unemployment reached about 6 million in 1932, and Nazi votes rose as the Depression deepened","correct":true,"feedback":"Precise knowledge that supports the source."},{"text":"Hitler was the leader of Germany","correct":false,"feedback":"Too general to help.","tag":"generic_knowledge"}],"reveal":"Own knowledge: about 6 million unemployed by 1932."}],"finalAnswer":"Source A is useful because it shows the Nazis targeting the unemployed with promises of hope. As 1932 Nazi propaganda it reveals the party''s message, which my knowledge supports — unemployment reached about 6 million as Nazi support grew. However, it can''t show why individual voters chose the Nazis, so it is useful for Nazi methods but limited on motives."},"guided":[{"question":"Which part of provenance is ''to persuade people to vote Nazi''?","marks":1,"answer":{"type":"choice","options":["Nature","Origin","Purpose"],"correct":2},"hints":["Is it about what it is, who made it, or why?","It explains why it was made."],"solution":"Purpose: why the source was made."}],"exam":[{"question":"A diary entry written in 1940 by a London teenager describes sleeping in an Underground station during the Blitz. How useful is this source for an enquiry into the experience of civilians in the Blitz?","marks":8,"answer":{"type":"extended"},"markScheme":[{"point":"Uses the content to show what the source reveals about civilian experience","marks":2},{"point":"Uses nature (private diary) to judge honesty","marks":1},{"point":"Uses origin (date, author, place) to judge value and limits","marks":2},{"point":"Brings in relevant, specific own knowledge","marks":2},{"point":"Reaches a supported judgement about usefulness","marks":1}],"modelAnswer":"The diary is useful because it gives a first-hand account of sheltering in the Underground. As a private diary it was probably not written to persuade, so it may be honest. It was written in 1940 during the Blitz, so the experience is fresh. However, it is one teenager in London, and my knowledge shows many people used Anderson shelters or stayed at home, so it can''t represent all civilians. Overall it is useful for an individual''s experience but limited for civilians as a whole.","mistakeTags":["source_content_only","no_judgement","generic_knowledge"]}]}'::jsonb, 'published')
