  where public.lessons.content is distinct from excluded.content;
insert into public.lessons (topic_id, content, status) values ('0b43bcbc-1b4b-5549-a127-c25597d9a93d', '{"style":"explanation","summary":"Explain why an event happened by linking each cause to the outcome, showing how causes connect, and avoiding simply listing factors.","knowledge":["A cause must be linked to the outcome — say HOW it led to the event.","Causes can be long-term, short-term or triggers.","Causes often connect: one made another more powerful.","Use specific evidence: names, dates and figures."],"vocabulary":[{"term":"Trigger","meaning":"The immediate event that sets off a larger change."},{"term":"Long-term cause","meaning":"A factor that built up over years and made the event possible."}],"recognise":"''Explain why…'', ''Explain what was important about…''","commandWords":[{"word":"Explain why","meaning":"Give reasons and show how they led to the outcome."}],"method":[{"title":"Identify two or three causes","detail":"Choose different types if you can."},{"title":"Support each with evidence","detail":"Specific details from your knowledge."},{"title":"Link to the outcome","detail":"Use ''this led to'', ''as a result'', ''which meant''."},{"title":"Connect the causes","detail":"Show how one cause made another worse."}],"mistakes":[{"tag":"description_not_explanation","text":"Describing a cause without saying how it caused the outcome."},{"tag":"generic_knowledge","text":"No specific facts to support a point."}],"worked":{"question":"Explain why the Weimar Republic faced a crisis in 1923.","marks":8,"steps":[{"prompt":"What''s the first cause?","choices":[{"text":"The French and Belgians occupied the Ruhr in January 1923 when Germany missed reparations payments","correct":true,"feedback":"A specific cause with a date."},{"text":"Germany had problems","correct":false,"feedback":"Too vague.","tag":"generic_knowledge"}],"reveal":"Cause 1: the occupation of the Ruhr."},{"prompt":"How does it link to the crisis?","choices":[{"text":"Workers went on strike and the government printed money to pay them, which caused hyperinflation","correct":true,"feedback":"That''s the link — the cause leads to the outcome."},{"text":"The Ruhr was an important area","correct":false,"feedback":"Say what happened as a result.","tag":"description_not_explanation"}],"reveal":"Linked: printing money caused hyperinflation."},{"prompt":"How do you connect to a second cause?","choices":[{"text":"Hyperinflation made people lose faith in Weimar, encouraging extremists such as in the Munich Putsch in November 1923","correct":true,"feedback":"Connected causes show higher-level explanation."},{"text":"Also, there was the Munich Putsch.","correct":false,"feedback":"That just lists another event.","tag":"description_not_explanation"}],"reveal":"Connected: economic crisis fuelled political threats."}],"finalAnswer":"The occupation of the Ruhr in January 1923 led to strikes, and the government printed money to pay workers, causing hyperinflation. Savings became worthless, which made people lose faith in the Republic and encouraged extremists — Hitler attempted the Munich Putsch in November 1923."},"guided":[{"question":"Which phrase shows a cause being LINKED to an outcome?","marks":1,"answer":{"type":"choice","options":["Another cause was…","This led to…","In 1923…","Firstly…"],"correct":1},"hints":["Linking shows consequence.","Which phrase explains a result?"],"solution":"''This led to…'' links a cause to its effect."}],"exam":[{"question":"Explain why William won the Battle of Hastings in 1066.","marks":8,"answer":{"type":"extended"},"markScheme":[{"point":"Identifies at least two relevant causes (e.g. Harold''s exhausted army, Norman tactics, luck with the wind)","marks":2},{"point":"Supports causes with specific knowledge","marks":2},{"point":"Explains how each cause led to William''s victory","marks":3},{"point":"Shows how causes connected","marks":1}],"modelAnswer":"Harold''s army had just fought Harald Hardrada at Stamford Bridge and marched about 250 miles south, so his troops were exhausted. This made them vulnerable to William''s tactics: the Normans used feigned retreats, tempting Saxons to break the shield wall, which let Norman cavalry attack. Harold''s death late in the battle left the English leaderless, so the army collapsed. The exhaustion made the shield wall harder to hold, linking the two causes.","mistakeTags":["description_not_explanation","generic_knowledge"]}]}'::jsonb, 'published')
